:root {
  --color-primary: #7380ec;
  --color-dark: #363949;
  --color-background: #f6f6f9;
  --sidebar-bg: #ffffff;
  --sidebar-width: 250px;
  --sidebar-width-collapsed: 80px;
  --nav-link-color: #7d8da1;
  --nav-link-hover-bg: #f0f0f0;
  --box-shadow: 0 1rem 2rem rgba(132, 139, 200, 0.18);
}

body {
  margin: 0;
  font-family: "Poppins", sans-serif;
  background-color: var(--color-background);
}

.app-container {
  display: grid;
  grid-template-columns: var(--sidebar-width) 1fr;
  transition: grid-template-columns 0.3s ease;
}

/* --- SIDEBAR --- */
.sidebar {
  background-color: var(--sidebar-bg);
  height: 100vh;
  display: flex;
  flex-direction: column;
  box-shadow: var(--box-shadow);
  transition: width 0.3s ease;
  position: sticky;
  top: 0;
  width: var(--sidebar-width);
}

.main-nav {
  flex-grow: 1;
  margin-top: 2rem;
}

.main-nav ul {
  list-style: none;
  padding: 0;
  margin: 0;
}

.main-nav a {
  display: flex;
  align-items: center;
  padding: 1rem 1.5rem;
  color: var(--nav-link-color);
  text-decoration: none;
  transition: background-color 0.2s, color 0.2s;
  white-space: nowrap;
  overflow: hidden;
}

.main-nav a:hover {
  background-color: var(--nav-link-hover-bg);
  color: var(--color-primary);
}

.main-nav a.active {
  background-color: var(--color-primary);
  color: white;
}

.main-nav a i {
  font-size: 1.5rem;
  min-width: 50px;
  text-align: center;
  transition: none; /* Evita que o ícone se mova */
}

.sidebar-footer {
  padding: 1rem;
  border-top: 1px solid #eee;
  display: flex;
  align-items: center;
  justify-content: space-between;
  overflow: hidden;
}

.logout-button {
  display: flex;
  align-items: center;
  color: var(--nav-link-color);
  text-decoration: none;
  white-space: nowrap;
}

.sidebar-toggle-button {
  background: none;
  border: none;
  cursor: pointer;
  font-size: 1.2rem;
  color: var(--nav-link-color);
  transition: transform 0.3s ease;
}

/* --- ESTADO RECOLHIDO --- */
html.sidebar-collapsed .app-container {
  grid-template-columns: var(--sidebar-width-collapsed) 1fr;
}

html.sidebar-collapsed .sidebar {
  width: var(--sidebar-width-collapsed);
}

html.sidebar-collapsed .nav-text {
  display: none;
}

html.sidebar-collapsed .sidebar-toggle-button i {
  transform: rotate(180deg);
}

/* --- MAIN CONTENT --- */
.main-content {
  padding: 2rem;
}
